var r=`1244-jerk-pork`;var n=`world-1244`;var t=`JM`;var a=`central-america-caribbean`;var o=4;var s=262;var d={en:`Jerk Pork`,ua:`Свинина джерк`};var g={en:`Jerk Pork is a dish from Jamaica featuring pork shoulder, jerk marinade, thyme, garlic. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Свинина джерк, страва кухні країни Ямайка з такими основними складниками: свиняча лопатка, маринад джерк, чебрець, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var m=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 160 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 160 хвилин.`,t:[`marinating`],m:160,i:[[`pork-shoulder`,1e3,`g`],[`jerk-marinade`,180,`g`],[`thyme`,4,`sprig`],[`garlic`,4,`clove`]]},{en:`Roast the already seasoned food in a preheated oven until tender and safely cooked, using a thermometer for meat or poultry.`,ua:`Запікайте вже приправлені продукти в розігрітій духовці до м’якості та готовності, перевіряючи температуру м’яса термометром.`,t:[`roasting`],m:85,i:[]},{en:`Grill the marinated portions from the preceding steps, turning to cook evenly and checking the safe internal temperature.`,ua:`Готуйте замариновані порції на грилі, перевертаючи для рівномірного нагрівання та перевіряючи безпечну температуру всередині.`,t:[`grilling`],m:14,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime`,2,`pcs`]]}];var h={slug:r,id:n,country:`JM`,region:a,servings:4,minutes:262,title:d,text:g,steps:m};export{t as country,h as default,n as id,s as minutes,a as region,o as servings,r as slug,m as steps,g as text,d as title};